<?php
namespace Avanik;
defined('ABSPATH') || exit;
interface NotificationProviderConnectionTestInterface { public function testConnection(array $credentials): array; }
final class NotificationProviderConnectionTest {
 public static function register(): void { add_action('admin_post_avanik_test_provider_connection',[self::class,'handle']); }
 public static function test(string $provider): array { $provider=sanitize_key($provider); if(!$provider)return ['ok'=>false,'code'=>'invalid_provider','message'=>'Invalid provider.']; $settings=NotificationProviderSettings::get(); if(empty($settings[$provider])||empty($settings[$provider]['enabled']))return ['ok'=>false,'code'=>'provider_disabled','message'=>'Provider is disabled or not configured.']; if(NotificationProviderHealth::is_disabled($provider,'internal'))return ['ok'=>false,'code'=>'circuit_open','message'=>'Provider is blocked by circuit breaker.']; $adapter_name=(string)($settings[$provider]['adapter']??''); if($adapter_name===''||$adapter_name==='core')return ['ok'=>false,'code'=>'no_external_adapter','message'=>'No external adapter is registered for this provider.']; $adapter=NotificationProviderAdapterRegistry::resolve('internal','provider_connection_test',[],0); if(!$adapter||$adapter->provider()!==$provider||!($adapter instanceof NotificationProviderConnectionTestInterface))return ['ok'=>false,'code'=>'test_not_supported','message'=>'This provider adapter does not expose a connection test.']; $credentials=NotificationCredentialVault::get($provider); if(!$credentials)return ['ok'=>false,'code'=>'missing_credentials','message'=>'No credentials are stored for this provider.']; try{$result=$adapter->testConnection($credentials);return is_array($result)?$result:['ok'=>false,'code'=>'invalid_adapter_result','message'=>'Adapter returned an invalid result.'];}catch(\Throwable $e){return ['ok'=>false,'code'=>'adapter_exception','message'=>'Provider connection test failed.'];} }
 public static function handle(): void { if(!current_user_can('manage_options'))wp_die('Forbidden',403); $provider=sanitize_key($_POST['provider']??'');check_admin_referer('avanik_test_provider_connection_'.$provider);$result=self::test($provider);$code=sanitize_key((string)($result['code']??($result['ok']?'ok':'failed')));$message=sanitize_text_field((string)($result['message']??($result['ok']?'Connection successful.':'Connection failed.')));$url=admin_url('options-general.php?page=avanik-provider-credentials&test='.($result['ok']?'success':'failed').'&code='.rawurlencode($code).'&message='.rawurlencode($message));wp_safe_redirect($url);exit; }
}